/**
 * Jobs and skills, exported verbatim from the shipping build.
 *
 * Generated by `analysis/export_jobs_web.py` from the 15 `JobSkillInfo` and 5
 * `JobInfo` ScriptableObjects plus the game's own `LocalizationJson`.
 * Do not hand-edit: re-run the exporter.
 *
 * `kind` is the original's own taxonomy, read straight off the asset flags:
 *   pet     - `isPet`, auto-summoned (Wolf / Bear / Falcon)
 *   passive - `isPassive`, no button; it replaces the auto-attack on a probability
 *             (`CharacterAttacker.cs:149-154` rolls Lightning/fire/blizzard)
 *   buff    - `isBuff`, auto-cast whenever ready (`TryCastReadyBuffSkills`)
 *   shot    - `isShotByArcher`, the archer's auto-attack fires it
 *   cast    - neither; cast on cooldown by `CallNonShotSkills` (SniperScope, BatSwarm)
 */

export type SkillKind = 'pet' | 'passive' | 'buff' | 'shot' | 'cast';

export interface JobSkillDef {
  id: string;
  /** The ScriptableObject's asset name, e.g. `Job0_Multishot`. */
  asset: string;
  /** Owning job index 0..4, and the skill's slot within it. */
  job: number;
  slot: number;
  kind: SkillKind;
  maxLevel: number;
  /** Per-level ClawCurrency price; `cost[level - 1]`. */
  cost: number[];
  /** All of these are indexed by `level - 1`, clamped, exactly as the original's
   *  `GetXForLevel` helpers do. */
  cooldowns: number[];
  damageMultipliers: number[];
  numberOfHits: number[];
  pierceCounts: number[];
  numberOfTurns: number[];
  durations: number[];
  buffValues: number[];
  buffDurations: number[];
  isBuff: boolean;
  isPassive: boolean;
  isPet: boolean;
  isShotByArcher: boolean;
  passiveStat: string | null;
  passiveStatProp: string | null;
  passiveEffectValueEquation: string;
  passiveEffectLabelKey: string;
  passiveEffectSuffix: string;
  buffStat: string | null;
  buffStatProp: string | null;
  buffEffectLabelKey: string;
  buffEffectSuffix: string;
  petAttackRange: number;
  petAttackRadius: number;
  petAttackSpeed: number;
  petHealthMultipliers: number[];
  petAttackChances: number[];
  /** `skillNameInStatsData`, the prefix the original writes its stats under. */
  skillNameInStatsData: string;
  icon: string;
  titleZh: string;
  descZh: string;
  titleEn: string;
  descEn: string;
}

export interface JobDef {
  index: number;
  /** `JobInfo.UnlockCost`, paid in ClawCurrency. `JobsUIManager` also requires the
   *  previous job to be unlocked, so the ladder is strictly ordered. */
  unlockCost: number;
  skills: string[];
  passiveStat: string | null;
  passiveStatProp: string | null;
  passiveValue: number;
  bonusLabelKey: string;
  bonusTooltipKey: string;
  /** The game's own job name and passive wording, from `LocalizationJson`. */
  titleZh: string;
  titleEn: string;
  passiveTitleZh: string;
  passiveTextZh: string;
  passiveDescZh: string;
}

